CREATE TABLE r AS SELECT a,b,sum(c)OVER(ORDER BY a GROUPS BETWEEN UNBOUNDED PRECEDING AND 1 FOLLOWING EXCLUDE CURRENT ROW) AS x1,sum(c)OVER(ORDER BY a GROUPS BETWEEN UNBOUNDED PRECEDING AND 1 FOLLOWING) AS x2,sum(c)OVER(ORDER BY a,b GROUPS BETWEEN UNBOUNDED PRECEDING AND 1 FOLLOWING EXCLUDE CURRENT ROW) AS x3,sum(c)OVER(ORDER BY a,b GROUPS BETWEEN UNBOUNDED PRECEDING AND 1 FOLLOWING) AS x4 FROM t3;